/**
 * An application's command menus in one row (`design/components/menubar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/menubar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/menu'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Icon,
  afresh,
  afterRender,
  agentMember,
  chooseMenubarEntry,
  claimSlot,
  classes,
  createCell,
  createDerived,
  elementRef,
  followHighlight,
  itemOf,
  menubarChoices,
  menubarEdge,
  menubarEntries,
  menubarNeighbour,
  menubarStop,
  mergeParts,
  ownerContext,
  provide,
  roveMenubar,
  scope,
  useDirection,
  useMachine,
  useMediaQuery,
  watchEffect,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/overlays/menubar.module.css'
import Button from '../controls/Button'
import Kbd from '../structure/Kbd'
import Menu, { type MenuEntry } from './Menu'
import MenubarSubmenu from './MenubarSubmenu'

export interface MenubarMenu {
  label: string
  entries: MenuEntry[]
  disabled?: boolean
}

export interface MenubarProps {
  /**
   * The title whose menu is open on mount, for galleries and tests; screens let the user open
   * it.
   */
  defaultOpen?: string
  /**
   * Names the bar, and the one Button the bar becomes at a phone's width.
   */
  label: string
  menus: MenubarMenu[]
}

/** What Menubar hands its compound parts. */
export interface MenubarOwner {
  readonly api: zag.Api
  readonly service: zag.Service
  readonly handOff: unknown
}

/** An application's command menus in one row. */
export default function Menubar(given: MenubarProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    provide(ownerContext<MenubarOwner>('Menubar'), {
      get api() {
        return api.value
      },
      get service() {
        return service
      },
      get handOff() {
        return handOff.value
      },
    })
    const uid = createUniqueId()
    const bar = elementRef<HTMLElement>()
    const panel = elementRef<HTMLElement>()
    const phone = useMediaQuery('phone')
    const last = createCell((props.defaultOpen ?? null) as string | null)
    const stop = createDerived(() => menubarStop(props.menus, last.value))
    const collapsed = createDerived(() => menubarEntries(props.menus))
    const documentDirection = useDirection(() => bar.value)
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          defaultOpen: props.defaultOpen !== undefined,
          defaultTriggerValue: props.defaultOpen,
          positioning: { placement: 'bottom-start', gutter: 2 },
          onSelect: (details) => {
            entries.value.forEach(
              (entry) => 'onSelect' in entry && entry.label === details.value && entry.onSelect(),
            )
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const entries = createDerived(
      () => props.menus.find((menu) => menu.label === api.value.triggerValue)?.entries ?? [],
    )
    const handOff = createDerived(
      () =>
        (event: KeyboardEvent, child?: { setOpen(open: boolean): void }): void => {
          const to = menubarNeighbour(event, bar.value, panel.value)
          const next = to === undefined ? undefined : props.menus[to]
          if (next === undefined) return
          event.preventDefault()
          event.stopPropagation()
          child?.setOpen(false)
          api.value.setTriggerValue(next.label)
          afterRender(() => {
            const first = menubarEdge(panel.value, 'first')?.getAttribute('data-value')
            if (first) api.value.setHighlightedValue(first)
          })
        },
    )
    const hover = createDerived(() => (event: Event, menu: MenubarMenu): void => {
      if (!(event instanceof PointerEvent) || event.pointerType !== 'mouse') return
      if (menu.disabled === true) return
      if (!api.value.open || api.value.triggerValue === menu.label) return
      api.value.setTriggerValue(menu.label)
      // The machine reads an empty value as no row, so the last menu's row is not carried over.
      api.value.setHighlightedValue('')
    })
    const present = usePresence(
      () => api.value.open && !phone(),
      () => panel.value,
    )
    const effect1 = () => {
      followHighlight(panel.value, api.value.highlightedValue)
    }
    watchEffect(
      createMemo(() => api.value.highlightedValue),
      effect1,
      true,
    )
    const effect2 = () => {
      void (api.value.triggerValue && (last.value = api.value.triggerValue))
    }
    watchEffect(
      createMemo(() => api.value.triggerValue),
      effect2,
      false,
    )
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = agentMember({
        member: 'Menubar',
        element: () => bar.value,
        state: () => ({ open: api.value.open, entries: menubarChoices(props.menus) }),
        actions: {
          choose: {
            argument: 'id',
            run: (value) =>
              chooseMenubarEntry(props.menus, value) && api.value.open && api.value.setOpen(false),
          },
          close: () => api.value.open && api.value.setOpen(false),
        },
      })
      release3 = () => {
        ran()
      }
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    return (
      <>
        {phone() ? (
          <div class={styles.collapsed} data-member="menubar">
            <Menu
              items={collapsed.value}
              trigger={
                <Button
                  variant="ghost"
                  tone="neutral"
                  iconOnly={true}
                  icon="overflow"
                  label={props.label}
                />
              }
            />
          </div>
        ) : (
          <>
            {/* bar */}
            <div
              class={styles.bar}
              role="menubar"
              aria-label={props.label}
              data-member="menubar"
              ref={bar.attach}
            >
              <Each of={props.menus} by={(menu) => menu.label} renew>
                {(menu) => (
                  <button
                    {...mergeParts(api.value.getTriggerProps({ value: menu.label }), {
                      class: styles.title,
                      role: 'menuitem',
                      'data-menubar-part': 'title',
                      'data-state':
                        api.value.open && api.value.triggerValue === menu.label ? 'open' : 'closed',
                      'aria-expanded': api.value.open && api.value.triggerValue === menu.label,
                      'aria-controls':
                        api.value.open && api.value.triggerValue === menu.label
                          ? api.value.getContentProps().id
                          : undefined,
                      disabled: menu.disabled === true,
                      'data-disabled': menu.disabled === true ? '' : undefined,
                      tabindex: menu.label === stop.value ? 0 : -1,
                      onkeydown: ($event: KeyboardEvent) => roveMenubar($event),
                      onpointerenter: ($event: PointerEvent) => hover.value($event, itemOf(menu)),
                      onfocus: () => (last.value = menu.label),
                    })}
                  >
                    {menu.label}
                  </button>
                )}
              </Each>
            </div>
            <Portal>
              {afresh(() => (
                <>
                  {present() ? (
                    <div {...mergeParts(api.value.getPositionerProps())}>
                      {/* panel */}
                      <div
                        {...mergeParts(api.value.getContentProps(), {
                          class: styles.content,
                          style: {
                            '--radix-dropdown-menu-content-available-height':
                              'var(--available-height)',
                            '--radix-dropdown-menu-content-transform-origin':
                              'var(--transform-origin)',
                          },
                          hidden: undefined,
                          'data-menubar-part': 'panel',
                          'data-member': 'menubar',
                          onfocus: () => followHighlight(panel.value, api.value.highlightedValue),
                          'oncapture:keydown': ($event: KeyboardEvent) => handOff.value($event),
                        })}
                        ref={panel.attach}
                      >
                        <Each of={entries.value} by={(_entry, index) => index} renew>
                          {(entry) => (
                            <>
                              {entry.kind === 'separator' ? (
                                <div
                                  {...mergeParts(api.value.getSeparatorProps(), {
                                    class: styles.separator,
                                  })}
                                />
                              ) : entry.kind === 'label' ? (
                                <div class={styles.groupLabel}>{entry.label}</div>
                              ) : entry.kind === 'checkbox' ? (
                                <div
                                  {...mergeParts(
                                    api.value.getOptionItemProps({
                                      type: 'checkbox',
                                      value: entry.label,
                                      checked: entry.checked,
                                      disabled: entry.disabled,
                                      closeOnSelect: false,
                                      onCheckedChange: entry.onCheckedChange,
                                    }),
                                    {
                                      class: classes(styles.item, styles.checkbox),
                                      tabindex: '-1',
                                      onfocus: () => api.value.setHighlightedValue(entry.label),
                                    },
                                  )}
                                >
                                  <span class={styles.check}>
                                    {entry.checked ? <Icon name="confirm" size="sm" /> : null}
                                  </span>
                                  <span class={styles.label}>{entry.label}</span>
                                </div>
                              ) : entry.kind === 'submenu' ? (
                                <MenubarSubmenu entry={entry} />
                              ) : (
                                <div
                                  {...mergeParts(
                                    api.value.getItemProps({
                                      value: entry.label,
                                      disabled: entry.disabled,
                                    }),
                                    {
                                      class: styles.item,
                                      'data-tone': entry.tone ?? 'neutral',
                                      tabindex: '-1',
                                      onfocus: () => api.value.setHighlightedValue(entry.label),
                                    },
                                  )}
                                >
                                  {entry.icon !== undefined ? (
                                    <span class={styles.glyph}>
                                      <Icon name={entry.icon} size="sm" />
                                    </span>
                                  ) : null}
                                  <span class={styles.label}>{entry.label}</span>
                                  {entry.kbd !== undefined ? (
                                    <span class={styles.hint}>
                                      <Kbd>{entry.kbd}</Kbd>
                                    </span>
                                  ) : null}
                                </div>
                              )}
                            </>
                          )}
                        </Each>
                      </div>
                    </div>
                  ) : null}
                </>
              ))}
            </Portal>
          </>
        )}
      </>
    )
  })
}
